import math

def ar1_interval_halfwidth(phi, sigma2, h, z=1.96):
    if phi == 1:
        return z * math.sqrt(sigma2 * h)                      # random walk: no shock fades
    var = sigma2 * (1 - phi ** (2 * h)) / (1 - phi ** 2)     # sum of sigma2 * phi^(2j)
    return z * math.sqrt(var)

